#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Adiciona o Protocolo de Cancelamento (PDF) ao index.html do Painel Administrativo da Ensina Book.

Uso:  python3 aplicar_protocolo.py /caminho/para/index.html

- Faz um backup (index.html.bak-protocolo-AAAAMMDD-HHMMSS) antes de mudar qualquer coisa.
- Se o protocolo ja estiver instalado, nao faz nada.
- Se algum trecho esperado nao for encontrado, para sem alterar o arquivo.
"""
import sys, shutil, datetime

if len(sys.argv) != 2:
    sys.exit("Uso: python3 aplicar_protocolo.py /caminho/para/index.html")
caminho = sys.argv[1]
s = open(caminho, encoding="utf-8").read()

if "data-protocolo" in s:
    print("O protocolo ja esta instalado neste arquivo. Nada foi alterado.")
    sys.exit(0)

JS = '\n    // ======================================================\n    // PROTOCOLO DE CANCELAMENTO (PDF)\n    // Gera um PDF com o protocolo pra enviar ao cliente,\n    // registrando a data em que o cancelamento será feito.\n    // O número do protocolo começa com as iniciais do vendedor\n    // (ex.: Thiago Ferreira -> "TF-2026-123456") e fica salvo no\n    // registro, pra sair igual se o PDF for gerado de novo.\n    // ======================================================\n    let protocoloEmEdicao = null; // { item, venda }\n\n    // Iniciais do vendedor: primeira letra do primeiro e do último nome\n    function iniciaisVendedor(nome) {\n      const partes = String(nome || \'\')\n        .normalize(\'NFD\').replace(/[\\u0300-\\u036f]/g, \'\')\n        .replace(/[^A-Za-z\\s]/g, \' \').trim().split(/\\s+/).filter(Boolean);\n      if (!partes.length) return \'\';\n      if (partes.length === 1) return partes[0].slice(0, 2).toUpperCase();\n      return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();\n    }\n\n    function gerarNumeroProtocolo(nomeVendedor) {\n      const ano = new Date().getFullYear();\n      const aleatorio = Math.floor(100000 + Math.random() * 900000);\n      const iniciais = iniciaisVendedor(nomeVendedor) || \'XX\';\n      return iniciais + \'-\' + ano + \'-\' + aleatorio;\n    }\n\n    function hojeIso() {\n      const d = new Date();\n      return d.getFullYear() + \'-\' + String(d.getMonth() + 1).padStart(2, \'0\') + \'-\' + String(d.getDate()).padStart(2, \'0\');\n    }\n\n    function dataParaIso(data) {\n      return data.getFullYear() + \'-\' + String(data.getMonth() + 1).padStart(2, \'0\') + \'-\' + String(data.getDate()).padStart(2, \'0\');\n    }\n\n    function abrirModalProtocolo(idCancelamento) {\n      Promise.all([\n        apiFetch(\'/cancelamentos/\' + idCancelamento).then(function (r) { return r.json(); }),\n        apiFetch(\'/vendas\').then(function (r) { return r.ok ? r.json() : []; }).catch(function () { return []; })\n      ])\n        .then(function (resultado) {\n          const item = resultado[0];\n          const venda = (resultado[1] || []).find(function (v) {\n            return String(v.numeroContrato) === String(item.numeroContrato);\n          }) || {};\n          protocoloEmEdicao = { item: item, venda: venda };\n\n          // Sugere a data prevista: a já salva, ou o fim do prazo do setor\n          let dataPrevista = item.protocoloDataPrevista || \'\';\n          if (!dataPrevista && PRAZO_DIAS_UTEIS.hasOwnProperty(item.setor) && item.dataInformadoCliente) {\n            dataPrevista = dataParaIso(somarDiasUteis(item.dataInformadoCliente, PRAZO_DIAS_UTEIS[item.setor]));\n          }\n\n          const nomeVendedor = venda.vendedor || item.vendedor || \'\';\n          protocoloEmEdicao.vendedor = nomeVendedor;\n          document.getElementById(\'mp-resumo\').textContent =\n            (item.clienteNome || \'Cliente\') + \' · Contrato nº \' + (item.numeroContrato || \'—\') +\n            \' · Vendedor: \' + (nomeVendedor || \'não encontrado\');\n          document.getElementById(\'mp-numero\').value = item.protocoloNumero || gerarNumeroProtocolo(nomeVendedor);\n          document.getElementById(\'mp-cpf\').value = item.clienteCpf || venda.clienteCpf || \'\';\n          document.getElementById(\'mp-data-solicitacao\').value = item.dataPedidoCancelamento || \'\';\n          document.getElementById(\'mp-data-prevista\').value = dataPrevista;\n          document.getElementById(\'modal-protocolo\').style.display = \'flex\';\n          document.getElementById(\'mp-data-prevista\').focus();\n        })\n        .catch(function () { alert(\'Não foi possível carregar os dados deste cancelamento.\'); });\n    }\n\n    function fecharModalProtocolo() {\n      document.getElementById(\'modal-protocolo\').style.display = \'none\';\n      protocoloEmEdicao = null;\n    }\n\n    document.getElementById(\'mp-cancelar\').addEventListener(\'click\', fecharModalProtocolo);\n    document.getElementById(\'modal-protocolo\').addEventListener(\'click\', function (e) {\n      if (e.target.id === \'modal-protocolo\') fecharModalProtocolo();\n    });\n    document.addEventListener(\'keydown\', function (e) {\n      if (e.key === \'Escape\' && document.getElementById(\'modal-protocolo\').style.display === \'flex\') fecharModalProtocolo();\n    });\n\n    document.getElementById(\'mp-gerar\').addEventListener(\'click\', function () {\n      if (!protocoloEmEdicao) return;\n      let numero = document.getElementById(\'mp-numero\').value.trim().toUpperCase();\n      const dataPrevista = document.getElementById(\'mp-data-prevista\').value;\n      if (!dataPrevista) {\n        alert(\'Informe a data prevista para o cancelamento.\');\n        document.getElementById(\'mp-data-prevista\').focus();\n        return;\n      }\n      if (!numero) numero = gerarNumeroProtocolo(protocoloEmEdicao.vendedor);\n\n      const item = protocoloEmEdicao.item;\n      const dados = {\n        numero: numero,\n        cliente: item.clienteNome || \'\',\n        cpf: document.getElementById(\'mp-cpf\').value.trim(),\n        contrato: item.numeroContrato || \'\',\n        dataSolicitacao: document.getElementById(\'mp-data-solicitacao\').value,\n        dataPrevista: dataPrevista\n      };\n\n      if (!gerarPdfProtocolo(dados)) return;\n\n      // Guarda o número e a data no registro, pra reaproveitar depois\n      item.protocoloNumero = numero;\n      item.protocoloDataPrevista = dataPrevista;\n      apiFetch(\'/cancelamentos/\' + item.id, {\n        method: \'PUT\',\n        headers: { \'Content-Type\': \'application/json\' },\n        body: JSON.stringify(item)\n      }).catch(function () { console.error(\'Falha ao salvar o protocolo no cancelamento \' + item.id); });\n\n      fecharModalProtocolo();\n    });\n\n    function gerarPdfProtocolo(d) {\n      if (typeof window.jspdf === \'undefined\') {\n        alert(\'Não foi possível carregar a biblioteca de PDF. Verifique sua conexão com a internet e tente novamente.\');\n        return false;\n      }\n      const doc = new window.jspdf.jsPDF({ unit: \'mm\', format: \'a4\' });\n      const W = 210, H = 297;\n      const PRETO = [28, 27, 25], DOURADO = [201, 162, 39], DOURADO_CLARO = [246, 237, 207];\n      const CREME = [251, 248, 241], CINZA = [107, 103, 96], CAMPO = [245, 242, 234];\n\n      // Fundo creme\n      doc.setFillColor.apply(doc, CREME); doc.rect(0, 0, W, H, \'F\');\n\n      // Faixa preta do topo, com a logo centralizada\n      doc.setFillColor.apply(doc, PRETO); doc.rect(0, 0, W, 53, \'F\');\n      doc.setDrawColor.apply(doc, DOURADO);\n      doc.setLineWidth(0.45); doc.line(0, 53, W, 53);\n      doc.setLineWidth(0.2); doc.line(0, 54.8, W, 54.8);\n      doc.setFillColor.apply(doc, DOURADO); doc.circle(W / 2, 22, 14.2, \'F\');\n      try { doc.addImage(LOGO_ENSINA_BOOK, \'PNG\', W / 2 - 13, 9, 26, 26); } catch (e) { /* segue sem a logo */ }\n      doc.setFont(\'times\', \'normal\'); doc.setFontSize(9); doc.setTextColor.apply(doc, DOURADO);\n      doc.text(\'E N S I N A   B O O K\', W / 2, 43, { align: \'center\' });\n      doc.setFont(\'helvetica\', \'normal\'); doc.setFontSize(7); doc.setTextColor(191, 185, 172);\n      doc.text(\'ATENDIMENTO AO CLIENTE\', W / 2, 48, { align: \'center\' });\n\n      // Título\n      doc.setFont(\'times\', \'bold\'); doc.setFontSize(24); doc.setTextColor.apply(doc, PRETO);\n      doc.text(\'Protocolo de Cancelamento\', W / 2, 74, { align: \'center\' });\n      doc.setDrawColor.apply(doc, DOURADO); doc.setLineWidth(0.35); doc.line(W / 2 - 11, 78.5, W / 2 + 11, 78.5);\n\n      // Cartão branco com os dados\n      const cx = 18, cw = W - 36, ctop = 87, ch = 92;\n      doc.setFillColor(233, 227, 212); doc.roundedRect(cx + 0.8, ctop + 1, cw, ch, 3.5, 3.5, \'F\');\n      doc.setFillColor(255, 255, 255); doc.setDrawColor(228, 223, 211); doc.setLineWidth(0.3);\n      doc.roundedRect(cx, ctop, cw, ch, 3.5, 3.5, \'FD\');\n      doc.setFillColor.apply(doc, DOURADO); doc.rect(cx + 1.2, ctop, cw - 2.4, 2, \'F\');\n\n      const pad = 9, inner = cw - 2 * pad, metade = (inner - 6) / 2;\n      function campo(rotulo, valor, x, y, largura) {\n        doc.setFont(\'helvetica\', \'bold\'); doc.setFontSize(7); doc.setTextColor.apply(doc, CINZA);\n        doc.text(rotulo.toUpperCase(), x, y);\n        doc.setFillColor.apply(doc, CAMPO); doc.roundedRect(x, y + 2, largura, 8.5, 1.2, 1.2, \'F\');\n        doc.setFont(\'helvetica\', \'normal\'); doc.setFontSize(10.5); doc.setTextColor.apply(doc, PRETO);\n        doc.text(String(valor || \'—\'), x + 3, y + 7.6);\n      }\n      let y = ctop + 12;\n      campo(\'Protocolo nº\', d.numero, cx + pad, y, metade);\n      campo(\'Contrato nº\', d.contrato, cx + pad + metade + 6, y, metade);\n      y += 19;\n      campo(\'Nome do cliente\', d.cliente, cx + pad, y, inner);\n      y += 19;\n      campo(\'CPF\', d.cpf, cx + pad, y, metade);\n      campo(\'Data da solicitação\', formatarDataBR(d.dataSolicitacao), cx + pad + metade + 6, y, metade);\n      y += 18;\n\n      // Destaque dourado: data prevista para o cancelamento\n      doc.setFillColor.apply(doc, DOURADO_CLARO); doc.roundedRect(cx + pad - 3, y, inner + 6, 20, 2.5, 2.5, \'F\');\n      doc.setFont(\'helvetica\', \'bold\'); doc.setFontSize(7.5); doc.setTextColor(138, 109, 18);\n      doc.text(\'DATA PREVISTA PARA O CANCELAMENTO\', cx + pad, y + 5.5);\n      doc.setFillColor(255, 255, 255); doc.roundedRect(cx + pad, y + 8, inner, 9.5, 1.5, 1.5, \'F\');\n      doc.setFont(\'helvetica\', \'bold\'); doc.setFontSize(14); doc.setTextColor.apply(doc, PRETO);\n      doc.text(formatarDataBR(d.dataPrevista), cx + pad + 3, y + 15);\n\n      // Mensagem\n      let ty = ctop + ch + 14;\n      doc.setFont(\'helvetica\', \'normal\'); doc.setFontSize(10.5); doc.setTextColor.apply(doc, PRETO);\n      const texto = \'Informamos que a sua solicitação de cancelamento foi registrada com sucesso e será efetivada \' +\n        \'na data indicada acima. Assim que o cancelamento for concluído, enviaremos o comprovante pelos nossos canais de atendimento.\';\n      const linhas = doc.splitTextToSize(texto, W - 50);\n      doc.text(linhas, W / 2, ty, { align: \'center\', lineHeightFactor: 1.5 });\n      ty += linhas.length * 5.6 + 5;\n      doc.setFont(\'helvetica\', \'italic\'); doc.setFontSize(9.5); doc.setTextColor.apply(doc, CINZA);\n      doc.text(\'Guarde este número de protocolo para eventuais consultas.\', W / 2, ty, { align: \'center\' });\n\n      ty += 16;\n      doc.setFont(\'times\', \'italic\'); doc.setFontSize(12); doc.setTextColor.apply(doc, PRETO);\n      doc.text(\'Atenciosamente,\', W / 2, ty, { align: \'center\' });\n      ty += 6;\n      doc.setFont(\'helvetica\', \'bold\'); doc.setFontSize(10.5);\n      doc.text(\'Equipe de Atendimento – Ensina Book\', W / 2, ty, { align: \'center\' });\n      ty += 12;\n      doc.setFont(\'helvetica\', \'normal\'); doc.setFontSize(8.5); doc.setTextColor.apply(doc, CINZA);\n      doc.text(\'Emitido em: \' + formatarDataBR(hojeIso()), W / 2, ty, { align: \'center\' });\n\n      // Rodapé\n      doc.setFillColor.apply(doc, PRETO); doc.rect(0, H - 14, W, 14, \'F\');\n      doc.setDrawColor.apply(doc, DOURADO); doc.setLineWidth(0.35); doc.line(0, H - 14, W, H - 14);\n      doc.setFont(\'helvetica\', \'normal\'); doc.setFontSize(8.5); doc.setTextColor(217, 211, 197);\n      doc.text(\'Atendimento via WhatsApp  •  (11) 91660-2666\', W / 2, H - 5.5, { align: \'center\' });\n\n      const nomeArquivo = \'Protocolo_\' + d.numero + \'_\' + (d.cliente || \'cliente\').trim().replace(/\\s+/g, \'_\') + \'.pdf\';\n      doc.save(nomeArquivo);\n      return true;\n    }\n\n'
CSS = '\n  /* ===== Modal do Protocolo de Cancelamento ===== */\n  .modal-protocolo {\n    position: fixed; inset: 0; z-index: 1000;\n    background: rgba(17, 17, 17, 0.55);\n    display: flex; align-items: center; justify-content: center; padding: 16px;\n  }\n  .modal-protocolo__caixa {\n    background: var(--card-bg); border-radius: 12px; width: 100%; max-width: 560px;\n    padding: 24px; border-top: 5px solid var(--accent);\n    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.25);\n  }\n  .modal-protocolo__caixa h3 { margin: 0 0 4px; }\n  .modal-protocolo__sub { margin: 0 0 16px; color: var(--text-muted); font-size: 0.85rem; }\n'
MODAL = '\n  <!-- ===== MODAL: PROTOCOLO DE CANCELAMENTO ===== -->\n  <div id="modal-protocolo" class="modal-protocolo" style="display:none;" role="dialog" aria-modal="true" aria-labelledby="modal-protocolo-titulo">\n    <div class="modal-protocolo__caixa">\n      <h3 id="modal-protocolo-titulo">Protocolo de Cancelamento</h3>\n      <p class="modal-protocolo__sub" id="mp-resumo"></p>\n      <div class="form-grid">\n        <div class="form-field">\n          <label for="mp-numero">Nº do Protocolo</label>\n          <input type="text" id="mp-numero">\n        </div>\n        <div class="form-field">\n          <label for="mp-cpf">CPF do Cliente</label>\n          <input type="text" id="mp-cpf" placeholder="000.000.000-00">\n        </div>\n        <div class="form-field">\n          <label for="mp-data-solicitacao">Data da Solicitação</label>\n          <input type="date" id="mp-data-solicitacao">\n        </div>\n        <div class="form-field">\n          <label for="mp-data-prevista">Data Prevista para o Cancelamento</label>\n          <input type="date" id="mp-data-prevista">\n        </div>\n      </div>\n      <div class="form-actions">\n        <button class="btn-primary" type="button" id="mp-cancelar" style="background-color:var(--text-muted);">Cancelar</button>\n        <button class="btn-primary btn-accent" type="button" id="mp-gerar">Gerar PDF</button>\n      </div>\n    </div>\n  </div>\n'
HANDLER = "      // -------- PROTOCOLO DE CANCELAMENTO (PDF) --------\n      if (event.target.hasAttribute('data-protocolo')) {\n        event.preventDefault();\n        abrirModalProtocolo(id);\n        return;\n      }\n\n            "

ROW_OLD = """          '<a href="#" class="action-link" data-finalizar>Finalizar</a>' +
          '<a href="#" class="action-link" data-remove>Remover</a>' +"""
ROW_NEW = """          '<a href="#" class="action-link" data-finalizar>Finalizar</a>' +
          '<a href="#" class="action-link" data-protocolo>Protocolo</a>' +
          '<a href="#" class="action-link" data-remove>Remover</a>' +"""
VER = "      // -------- VER ANEXO (Carta Acordo) --------"
CARREGAR = "    function carregarCancelamentos() {"
EVENTOS = '<section id="eventos" class="section"'

for nome, trecho in [("botoes da linha", ROW_OLD), ("acao Ver Anexo", VER),
                     ("carregarCancelamentos", CARREGAR), ("</style>", "</style>"),
                     ("secao Eventos", EVENTOS)]:
    if s.count(trecho) != 1:
        sys.exit("Nao encontrei o trecho '" + nome + "' exatamente uma vez. Nenhuma alteracao foi feita.")

s = s.replace(ROW_OLD, ROW_NEW, 1)
s = s.replace(VER, HANDLER + VER.lstrip(), 1)
s = s.replace(CARREGAR, JS + CARREGAR, 1)
s = s.replace("</style>", CSS + "</style>", 1)
i = s.index(EVENTOS)
j = s.index("</section>", i) + len("</section>")
s = s[:j] + "\n" + MODAL + s[j:]

backup = caminho + ".bak-protocolo-" + datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
shutil.copy2(caminho, backup)
open(caminho, "w", encoding="utf-8").write(s)
print("Protocolo instalado com sucesso.")
print("Backup do arquivo original: " + backup)
